package com.mst.services;import com.mst.models.dto.SaleOutwardGatePassRequest;import com.mst.models.dto.SaleOutwardGatePassHistoryFilter;import com.mst.repositories.SaleOutwardGatePassRepository;import com.mst.security.CurrentUserContext;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SaleOutwardGatePassService{private final SaleOutwardGatePassRepository r;private final CurrentUserContext c;public SaleOutwardGatePassService(SaleOutwardGatePassRepository r,CurrentUserContext c){this.r=r;this.c=c;}public Object initial(){return r.initial(c.requireAccountingUser(),c.currentFinancialYearId());}public Object typeCode(String t){return Map.of("code",r.typeCode(c.requireAccountingUser(),c.currentFinancialYearId(),t));}public Object reference(int t,int n,LocalDate d){return r.reference(c.requireAccountingUser(),c.currentFinancialYearId(),t,n,d);}public Object history(SaleOutwardGatePassHistoryFilter f){var u=c.requireAccountingUser();return r.history(u,c.currentFinancialYearId(),r.canViewAllRecords(u,c.currentRoleName()),f);}public Object record(int id){return r.record(c.requireAccountingUser(),id);}public Object customers(String kind){return r.customersFor(c.requireAccountingUser(),kind);}public Object orderDetail(boolean so,LocalDate f,LocalDate t,int fn,int tn,int cu){return r.orderDetail(c.requireAccountingUser(),c.currentFinancialYearId(),so,f,t,fn,tn,cu);}@Transactional public Object save(SaleOutwardGatePassRequest x){return r.save(c.requireAccountingUser(),c.currentFinancialYearId(),x);}}
